import yaml


class ConfigurationModifier(object):
    IMAGE_PARAMETER = 'image'
    UVM_IMAGE_PARAMETER = 'uvm_image'

    @staticmethod
    def inject_robot_account(params, robot_account_parameter_name):
        robot_entry_str = """
              {robot_account_parameter_name}:
                system_info:
                  default_user:
                    name: robot
                users:
                - default
                - name: robot
                  gecos: Robot user for test automation purposes
                  primary-group: root
                  lock_passwd: false
                  plain_text_passwd: 'rastre1'
                  home: /home/robot
                  shell: /bin/bash
                  sudo:
                  - ALL=(ALL) NOPASSWD:ALL
                write_files:
                - content: |
                    robot
                  path: /etc/opt/nokia/setupsshkey.d/testusers
                  permissions: '0644'
                - content: '{{ "nonRootFullBashEnabled": true }}'
                  path: /usr/lib/umconfig.d/zzz.json
                  permissions: '0644'
        """.format(robot_account_parameter_name=robot_account_parameter_name)
        robot_entry = yaml.load(robot_entry_str, Loader=yaml.SafeLoader)
        params['parameters'].update(robot_entry)

    @staticmethod
    def update_image_name(params, image_name, image_parameter_key):
        """Update configuration_data's image key with passed image name.
        Raises TypeError if configuration_data is not loaded."""
        parameters = 'parameters'

        config_data = params
        if config_data is None:
            return
        elif parameters not in config_data:
            config_data[parameters] = {image_parameter_key: image_name}
        else:
            config_data[parameters][image_parameter_key] = image_name
